Topshiriq:

MATLAB da nutq signalining tahlilini amalga oshirish:

%% 1. Audio signalni yuklash

[signal, Fs] = audioread('D:/Voice 002.mp3');

signal = mean(signal, 2);   % Stereo bo'lsa monoga aylantirish

%% 2. Vaqt domenida ko'rish

t = (0:length(signal)-1) / Fs;

figure;

subplot(3,1,1);

plot(t, signal);

xlabel('Vaqt (s)');

ylabel('Amplituda');

title('Nutq signalining vaqt domenidagi korinishi');

%% 3. Chastota domeni (FFT)

N = length(signal);

Y = fft(signal);

f = (0:N-1)*(Fs/N);

subplot(3,1,2);

plot(f(1:floor(N/2)), abs(Y(1:floor(N/2))));

xlabel('Chastota (Hz)');

ylabel('Magnitude');

title('Nutq signalining FFT spektri');

xlim([0 Fs/2]);

%% 4. Spectrogrammma (umumiy korinish)

win = hamming(round(0.03*Fs));   % 30 ms oyna

overlap = round(0.02*Fs);        % 20 ms overlap

nfft = 1024;

subplot(3,1,3);

spectrogram(signal, win, overlap, nfft, Fs, 'yaxis');

title('Nutq signalining spektrogrammasi');

colorbar;

